<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {localFetch,readJson} from './http'
type Row={symbol:string;name:string;market:string;group:string;benchmark:string;close:number;status:string;reason:string;flags:string[];avg_amount:number|null;metrics:any;continuation:boolean;rolling_continuation:boolean;disposition:any;metadata_index?:string;foreign_source_day?:string}
const data=ref<any>(null),error=ref(''),busy=ref(false),loading=ref(true),mode=ref('fixed'),group=ref('stocks'),benchmark=ref('TAIEX_TR'),benchmarkMode=ref('matched'),search=ref(''),continuation=ref(true),unscored=ref(false),includeDisposed=ref(false),market=ref('TWSE'),page=ref(1),sort=ref('score'),direction=ref(-1),detail=ref<Row|null>(null),dialog=ref<HTMLElement|null>(null)
const groups=[['stocks','上市櫃個股'],['domestic','台股ETF'],['leveraged','台股槓桿／反向ETF'],['overseas','海外股票ETF'],['overseas_leveraged','海外槓桿／反向ETF'],['bonds','債券ETF'],['commodities','商品ETF'],['unmatched','分類待核對ETF']]
const sorts=[['score','60日標準化分數'],['car','60日β調整超額（日加總）'],['twenty','20日β調整超額（日加總）'],['alpha','日α（事後120日）'],['beta','目前曝險β'],['drawdown','60日最大回撤'],['liquidity','20日平均成交值'],['symbol','代碼']]
const taiwan=computed(()=>['stocks','domestic','leveraged'].includes(group.value))
const matched=computed(()=>taiwan.value&&benchmarkMode.value==='matched')
const effectiveBenchmark=computed(()=>matched.value?(market.value==='TPEX'?'TPEX_TR':'TAIEX_TR'):benchmark.value)
const benchmarkModeLabel=computed(()=>matched.value?'依掛牌市場配對（分市場排名）':taiwan.value?'全市場共同基準':'已核對海外／商品基準')
const benchNames=computed<Record<string,string>>(()=>data.value?.benchmark_names||{TAIEX_TR:'加權報酬指數',TPEX_TR:'櫃買報酬指數'})
const benchmarks=computed(()=>taiwan.value?['TAIEX_TR','TPEX_TR']:['overseas','overseas_leveraged'].includes(group.value)?['SPY','QQQ','DIA','SOXX','UNMATCHED']:['UNMATCHED'])
const groupRows=computed<Row[]>(()=>data.value?.rows?.filter((r:Row)=>r.group===group.value&&r.benchmark===effectiveBenchmark.value&&(market.value==='all'||r.market===market.value))||[])
const key=computed(()=>[group.value,effectiveBenchmark.value,market.value,includeDisposed.value?'include':'exclude'].join('|'))
const view=computed(()=>data.value?.views?.find((v:any)=>v.key===key.value))
const rankMap=computed<Record<string,number>>(()=>view.value?.ranks?.[mode.value]||{})
const counts=computed(()=>({all:groupRows.value.length,ok:view.value?.count||0,continuing:view.value?.continuation_count?.[mode.value]||0,unavailable:groupRows.value.filter(r=>r.status!=='ok').length,disposed:groupRows.value.filter(r=>r.disposition?.excluded_by_default).length}))
const alphaStats=computed(()=>view.value?.alpha_summary)
const strengthHeading=computed(()=>mode.value==='fixed'?'強度排行｜參數事前固定・表現已實現':'強度對照｜參數逐日估計・表現已實現')
function isContinuing(r:Row){return mode.value==='fixed'?r.continuation:r.rolling_continuation}
function val(r:Row,k:string):number|string|null{
 const m=r.metrics;if(k==='symbol')return r.symbol;if(k==='liquidity')return r.avg_amount;if(!m)return null
 if(k==='alpha')return typeof m.current?.intercept==='number'&&Number.isFinite(m.current.intercept)?m.current.intercept*100:null
 return k==='score'?m[mode.value].score:k==='car'?m[mode.value].car:k==='twenty'?m.twenty.car:k==='beta'?m.current.beta:k==='drawdown'?m.max_drawdown:null
}
const rows=computed(()=>groupRows.value.filter(r=>{
 if(!includeDisposed.value&&r.disposition?.excluded_by_default)return false
 if(search.value&&!(r.symbol+r.name).toLowerCase().includes(search.value.toLowerCase()))return false
 return unscored.value||(r.symbol in rankMap.value&&(!continuation.value||isContinuing(r)))
}).sort((a,b)=>{
 const av=val(a,sort.value),bv=val(b,sort.value)
 if(av===null)return bv===null?a.symbol.localeCompare(b.symbol):1;if(bv===null)return -1
 return (typeof av==='string'?av.localeCompare(String(bv)):Number(av)-Number(bv))*direction.value||a.symbol.localeCompare(b.symbol)
}))
const visible=computed(()=>rows.value.slice((page.value-1)*30,page.value*30)),pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/30)))
const mature=computed(()=>data.value?.validation?.mature?.filter((v:any)=>v.view_key===key.value+'|'+mode.value)||[])
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
async function load(){
 try{const r=await localFetch('/api/alpha-beta');const v=await readJson(r);if(!r.ok)throw new Error(v.error||'讀取失敗');if(disposed)return;data.value=v;busy.value=v.job?.status==='running';error.value='';if(busy.value)timer=setTimeout(load,2500)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}
}
async function refresh(){busy.value=true;error.value='';try{const r=await localFetch('/api/alpha-beta/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const v=await readJson(r);if(!r.ok)throw new Error(v.error||'更新失敗');await load()}catch(e){busy.value=false;error.value=e instanceof Error?e.message:String(e)}}
async function openDetail(row:Row){try{const r=await localFetch(`/api/alpha-beta/detail?symbol=${encodeURIComponent(row.symbol)}&benchmark=${encodeURIComponent(row.benchmark)}`);const v=await readJson(r);if(!r.ok)throw new Error(v.error||'詳情讀取失敗');if(!disposed){detail.value=v;await nextTick();dialog.value?.focus()}}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function num(v:unknown,d=2){return typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d}):'—'}
function pct(v:unknown,d=2){return typeof v==='number'&&Number.isFinite(v)?`${v>0?'+':''}${num(v,d)}%`:'—'}
function money(v:number|null){return v===null?'—':v>=1e8?`${num(v/1e8)} 億`:`${num(v/1e4,0)} 萬`}
function tone(v:unknown){return typeof v==='number'?(v>0?'up':v<0?'down':''):''}
function order(k:string){if(sort.value===k)direction.value*=-1;else{sort.value=k;direction.value=-1}}
function arrow(r:Row){return r.metrics?.beta_change.direction==='up'?'↑':r.metrics?.beta_change.direction==='down'?'↓':'≈'}
function alphaInterval(r:Row){const ci=r.metrics?.current?.alpha_ci;return ci?`${pct(ci[0]*100,3)}～${pct(ci[1]*100,3)}`:'待更新區間'}
function ranks(r:Row){return {fixed:view.value?.ranks?.fixed?.[r.symbol],rolling:view.value?.ranks?.rolling?.[r.symbol]}}
function dispositionLabel(r:Row){return r.disposition?.active?'處置中':r.disposition?.state==='unknown'?'處置待核對':r.disposition?.upcoming?'即將處置':r.disposition?.state==='ended'?'處置已結束':'未見期間內公告'}
function exportCsv(){
 const headings=['方法版本','資料日','報告發布時間','基準模式','排名市場','處置政策','代碼','名稱','市場','基準','計分方式','60日標準化分數','60日β調整超額%（日加總）','20日β調整超額%（日加總）','日α%（事後120日）','α HAC標準誤%','α HAC t比值','α 95%下界%','α 95%上界%','HAC落後日數','目前β','60日最大回撤%','平均成交值','處置判斷日','當時是否處置中','當時是否因處置排除','處置排除原因','處置公告紀錄','資料狀態']
 const body=rows.value.map(r=>{const f=r.metrics?.current,d=r.disposition;return [data.value.version,data.value.as_of,data.value.generated_at,benchmarkModeLabel.value,market.value,includeDisposed.value?'納入處置及待核對':'排除處置中及待核對',r.symbol,r.name,r.market,benchNames.value[r.benchmark]||'待核對',mode.value,val(r,'score'),val(r,'car'),val(r,'twenty'),val(r,'alpha'),f?.alpha_se==null?null:f.alpha_se*100,f?.alpha_t,f?.alpha_ci?.[0]==null?null:f.alpha_ci[0]*100,f?.alpha_ci?.[1]==null?null:f.alpha_ci[1]*100,f?.alpha_hac_lags,val(r,'beta'),val(r,'drawdown'),r.avg_amount,d?.screening_date,d?.active,!includeDisposed.value&&d?.excluded_by_default,d?.exclusion_reason,JSON.stringify(d?.announcements||[]),r.reason||'可排行']})
 const content='\ufeff'+[headings,...body].map(l=>l.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`Alpha-Beta-${data.value.version}-${data.value.as_of}-${group.value}-${effectiveBenchmark.value}-${market.value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
const chart=computed(()=>{const m=detail.value?.metrics;if(!m)return null;const series=[m.fixed.series,m.rolling.series];const vals=[0,...series.flat()] as number[];const lo=Math.min(...vals),hi=Math.max(...vals),span=Math.max(hi-lo,.5);const y=(v:number)=>140-(v-lo)/span*115
 return {fixed:series[0].map((v:number,i:number)=>`${35+i*530/59},${y(v)}`).join(' '),rolling:series[1].map((v:number,i:number)=>`${35+i*530/59},${y(v)}`).join(' '),zero:y(0),hi,lo}})
watch(group,()=>{benchmark.value=benchmarks.value[0]!;market.value=taiwan.value&&benchmarkMode.value==='matched'?'TWSE':'all'})
watch(benchmarkMode,()=>{if(matched.value&&market.value==='all')market.value='TWSE'})
watch([mode,group,benchmark,benchmarkMode,search,continuation,unscored,includeDisposed,market,sort,direction],()=>{page.value=1})
onMounted(load);onUnmounted(()=>{disposed=true;if(timer)clearTimeout(timer)})
</script>

<template>
<div class="ab-page">
 <header class="ab-heading"><div><div class="ab-eyebrow">RELATIVE STRENGTH · RISK EXPOSURE</div><h1>Alpha／Beta 排行</h1><p>強度排行與事後α分開解讀。<small class="ab-version">方法 {{data?.version||'—'}}</small></p></div><div class="ab-actions"><button :disabled="!data?.as_of" @click="exportCsv">匯出此排行</button><button class="ab-primary" :disabled="busy" @click="refresh">{{busy?'整理中…':'更新排行'}}</button></div></header>
 <div v-if="error" class="ab-error" role="alert">{{error}} <button @click="load">重新讀取</button></div>
 <div v-if="busy||['failed','partial'].includes(data?.job?.status)" class="ab-message" :class="{'ab-error':['failed','partial'].includes(data?.job?.status)}" role="status">{{data?.job?.message||'正在取得官方含息資料…'}}<small v-if="data?.as_of">更新期間保留 {{data.as_of}} 已完成排行</small></div>
 <div v-if="loading" class="ab-empty">讀取已保存排行…</div>
 <section v-else-if="!data?.as_of" class="ab-empty"><h2>建立含息 Alpha／Beta 排行</h2><p>首次更新需核對官方含息資料及公司事件。</p><button class="ab-primary" :disabled="busy" @click="refresh">{{busy?'正在建立…':'建立排行'}}</button></section>
 <template v-else>
 <div class="ab-summary"><article><small>資料收盤日</small><strong>{{data.as_of}}</strong><span>發布 {{data.generated_at?.slice(0,16).replace('T',' ')}}</span></article><article><small>目前組別可排行</small><strong>{{counts.ok}} <em>／{{counts.all}} 檔</em></strong><span>其中延續型 {{counts.continuing}} 檔</span></article><article><small>固定／滾動排序相關（Spearman）</small><strong data-testid="rank-correlation">{{num(view?.rank_correlation,4)}}</strong><span>比較 {{view?.count||0}} 檔 · 前10%重疊 {{num(view?.top_overlap,1)}}%</span></article><article><small>本版本前瞻驗證</small><strong>{{mature.length}} <em>組成熟紀錄</em></strong><span>按基準、市場及處置政策分開追蹤</span></article></div>
 <section class="ab-panel">
  <div class="ab-controls"><label>商品組別<select v-model="group" aria-label="Alpha Beta商品組別"><option v-for="g in groups" :key="g[0]" :value="g[0]">{{g[1]}}</option></select></label><label v-if="taiwan">基準模式<select v-model="benchmarkMode" aria-label="Alpha Beta基準模式"><option value="matched">依掛牌市場配對（分市場排名）</option><option value="common">全市場共同基準</option></select></label><label>排名市場<select v-model="market" aria-label="Alpha Beta排名市場"><option v-if="!matched" value="all">上市＋上櫃</option><option value="TWSE">上市</option><option value="TPEX">上櫃</option></select></label><label v-if="matched">自動配對基準<strong class="ab-auto-benchmark">{{benchNames[effectiveBenchmark]}}</strong></label><label v-else>比較基準<select v-model="benchmark" aria-label="Alpha Beta比較基準"><option v-for="b in benchmarks" :key="b" :value="b">{{benchNames[b]||'基準待核對'}}</option></select></label><label>計分方式<select v-model="mode" aria-label="Alpha Beta計分方式"><option value="fixed">事前固定版（預設）</option><option value="rolling">每日滾動版（對照）</option></select></label></div>
  <div class="ab-filters"><input v-model="search" placeholder="搜尋目前市場代碼／名稱" aria-label="搜尋Alpha Beta商品"/><label><input v-model="continuation" type="checkbox" :disabled="unscored"/>延續型強勢</label><label><input v-model="includeDisposed" type="checkbox"/>納入處置股／處置待核對</label><label><input v-model="unscored" type="checkbox"/>包含低流動性／待核對（{{counts.unavailable}}）</label><label>排序<select v-model="sort" aria-label="Alpha Beta排序欄位"><option v-for="s in sorts" :key="s[0]" :value="s[0]">{{s[1]}}</option></select></label><button @click="direction*=-1">{{direction===-1?'由大到小 ↓':'由小到大 ↑'}}</button></div>
  <div class="ab-statistics"><strong>全組α區間統計（{{alphaStats?.count||0}}檔；HAC 5日）</strong><span>近似95%區間不含0：{{alphaStats?.nonzero||0}}檔（正 {{alphaStats?.positive||0}}／負 {{alphaStats?.negative||0}}）；若全部α為0且區間覆蓋率正確，雜訊預期約 0.05 × {{alphaStats?.count||0}} ≈ {{num(alphaStats?.all_null_expected,1)}}檔。</span><small>未作多重比較校正。期望數不是本組實際錯誤數；股票相關與篩選會影響判讀。此統計不隨搜尋或延續型篩選縮小。</small></div>
  <div class="ab-explanation"><strong>{{strengthHeading}}</strong><span>{{mode==='fixed'?'評估期之前120日估計β及殘差波動，整段60日固定。':'每日以截至前一日120日估計β及殘差波動。'}} 累積超額是每日β調整報酬的單純加總，不是持有複利報酬。</span><span>流動性門檻：20日平均實際成交值 ≥ 2,000萬元。{{includeDisposed?'目前納入處置及待核對商品。':`預設排除發布日處置中／處置待核對 ${counts.disposed} 檔。`}}發布日 {{data.generated_at?.slice(0,10)}}；已結束處置不永久排除。</span></div>
  <div class="ab-table-wrap"><table class="ab-table"><thead><tr class="ab-column-groups"><th rowspan="2">#／商品</th><th colspan="3">{{strengthHeading}}</th><th colspan="2">歷史描述｜最新120日事後估計</th><th rowspan="2"><button @click="order('drawdown')">60日最大回撤</button></th><th rowspan="2">詳情</th></tr><tr><th><button @click="order('score')">60日標準化分數</button></th><th><button @click="order('car')">60日β調整超額</button><small>日報酬加總</small></th><th><button @click="order('twenty')">20日β調整超額</button><small>日報酬加總</small></th><th><button @click="order('alpha')">日α（事後120日）</button><small>HAC 5日・近似95%區間</small></th><th><button @click="order('beta')">目前曝險β</button></th></tr></thead><tbody><tr v-for="(r,i) in visible" :key="r.symbol" :class="{'ab-muted':r.status!=='ok'}"><td><div class="ab-stock"><span>{{(page-1)*30+i+1}}</span><div><strong>{{r.name}}</strong><small>{{r.symbol}} · {{r.market==='TWSE'?'上市':'上櫃'}}</small><span v-if="r.disposition?.active||r.disposition?.state==='unknown'||r.disposition?.upcoming" class="ab-disposition-badge" :class="{active:r.disposition?.active}">{{dispositionLabel(r)}}</span><small v-if="r.status!=='ok'" class="ab-warning">{{r.reason}}</small><small v-else-if="r.flags.length" class="ab-warning">{{r.flags[0]}}</small></div></div></td><td data-label="強度｜60日標準化分數"><strong>{{num(val(r,'score'))}}</strong><small v-if="ranks(r).fixed">固定 #{{ranks(r).fixed}}／滾動 #{{ranks(r).rolling}}</small><small v-else>未列本組排名</small></td><td data-label="60日β調整超額（日加總）" :class="tone(val(r,'car'))">{{pct(val(r,'car'))}}</td><td data-label="20日β調整超額（日加總）" :class="tone(val(r,'twenty'))">{{pct(val(r,'twenty'))}}</td><td data-label="描述｜日α（事後120日）" :class="tone(val(r,'alpha'))"><strong>{{pct(val(r,'alpha'),3)}}</strong><small class="ab-alpha-interval">{{r.metrics?alphaInterval(r):'—'}}</small></td><td data-label="描述｜目前曝險β">{{num(val(r,'beta'))}} <span v-if="r.metrics" :title="`β差值 ${num(r.metrics.beta_change.value)}；變化區間 ${r.metrics.beta_change.ci.map((v:number)=>num(v)).join('～')}`">{{arrow(r)}}</span><small v-if="r.metrics">R² {{num(r.metrics.current.r2)}}</small></td><td data-label="60日最大回撤" class="down">{{pct(val(r,'drawdown'))}}</td><td><button class="ab-detail" @click="openDetail(r)" :aria-label="`查看${r.name}詳細資料`">查看</button></td></tr></tbody></table></div>
  <div v-if="!rows.length" class="ab-empty"><h3>這組條件目前沒有可排行商品</h3><p>可切換排名市場、關閉延續型篩選，或勾選納入處置／資料待核對。</p></div>
  <div class="ab-pagination"><span>{{rows.length}} 檔 · 第 {{page}}／{{pages}} 頁</span><div><button :disabled="page<=1" @click="page--">上一頁</button><button :disabled="page>=pages" @click="page++">下一頁</button></div></div>
 </section>
 <details class="ab-panel ab-method"><summary>計算邏輯、資料範圍與使用限制</summary><p>日α＝最新120日含截距市場模型的回歸截距。無風險日利率近似為0；以每日%顯示，屬事後描述。α標準誤、t比值與近似95%區間皆用同一次回歸的HAC／Bartlett落後5日及有限樣本修正；不沿用事前波動。區間不含0不等於已驗證的選股能力。</p><p>β調整每日超額＝個股含息日報酬 − β × 含息基準日報酬。單純加總，不再扣歷史截距，亦不等於持有期複利報酬或傳統事件研究市場模型CAR。</p><p>固定版分數＝60日β調整超額加總 ÷（事前殘差日波動 × √60）。20日超額用其自己評估期之前120日β。滾動版分母為60個事前每日殘差變異數加總後開根號。標準化分數不是α t值。</p><p>延續型：60日與20日超額均正、60日後半段超額正。固定／滾動比較使用相同基準、市場及處置政策的共同可計分池；搜尋與延續型篩選不改變全組比較。</p><p>依掛牌市場配對時，上市對加權報酬、上櫃對櫃買報酬，分開排名。共同基準模式可跨市場比較，但所有商品仍使用同一基準。海外ETF按已核對的含息ETF代理與台幣換算，使用台股交易日前已完成的美股交易日；不匹配者不計分。</p><p>目前β比較最新120日與60交易日前120日估計，差值HAC已考慮重疊。週β僅作對照，與日β期間不同；本版未啟用日／週β敏感性警示或Dimson替代。</p><ul><li v-for="s in data.limitations" :key="s">{{s}}</li><li v-for="s in data.quality" :key="s">{{s}}</li></ul><p>此研究頁不會更改既有策略與手動帳戶。方法版本 {{data.version}}。</p></details>
 <details class="ab-panel ab-method"><summary>每日排行封存與後續20／60日驗證</summary><p>版本 {{data.validation.version||data.version}} · 首次 {{data.validation.first_published?.slice(0,16).replace('T',' ')||'—'}} · {{data.validation.snapshots}}個封存資料日。舊版本紀錄保留，分開評估，不倒填盤前訊號。</p><p>{{data.validation.note}}</p><p>封存當時每檔的公告、處置起訖日、發布日／收盤日處置狀態與排除原因；各基準、市場、計分方式及納入／排除政策的候選與前10%名單於發布時固定。追蹤從發布後下一交易日收盤起，滿20／60日才計結果。</p><p>成本假設：雙邊手續費各14.25bp、滑價各5bp；賣出稅個股30bp、ETF10bp。成本扣組合經濟報酬，不扣rank IC；缺價保留原分母並標示部分結果。為研究追蹤，非成交模擬。</p><div v-if="!mature.length" class="ab-empty">此版本與目前篩選政策尚無成熟樣本。</div><div v-else class="ab-table-wrap"><table class="ab-table"><thead><tr><th>版本／訊號日</th><th>追蹤區間</th><th>名單／有價</th><th>扣成本平均報酬</th><th>rank IC</th></tr></thead><tbody><tr v-for="v in mature" :key="v.as_of+v.days"><td>{{v.method_version}}<small>{{v.as_of}} · {{v.days}}日</small></td><td>{{v.start}}～{{v.end}}</td><td>{{v.selected}}／{{v.priced}}<small v-if="v.partial">缺價，部分結果</small></td><td>{{pct(v.mean_net_return)}}</td><td>{{num(v.rank_ic,4)}}</td></tr></tbody></table></div></details>
 </template>
 <div v-if="detail" class="ab-modal-backdrop" @click.self="detail=null"><section ref="dialog" class="ab-modal" role="dialog" aria-modal="true" :aria-label="detail.name+' Alpha Beta詳細資料'" tabindex="-1" @keydown.esc="detail=null"><header><div><small>{{detail.symbol}} · {{benchNames[detail.benchmark]||'基準待核對'}} · {{data?.version}}</small><h2>{{detail.name}}</h2></div><button @click="detail=null" aria-label="關閉詳細資料">關閉 ✕</button></header><p v-if="detail.reason" class="ab-warning">{{detail.reason}}</p><div v-if="detail.metrics" class="ab-detail-content"><div class="ab-alpha-summary"><small>歷史描述｜日α（最新120日事後回歸）</small><strong :class="tone(val(detail,'alpha'))">{{pct(val(detail,'alpha'),3)}} <em>／日</em></strong><span>{{detail.metrics.current.estimate_start}}～{{detail.metrics.current.estimate_end}}</span><span>HAC 5日標準誤 {{pct(detail.metrics.current.alpha_se*100,3)}}／日 · t比值 {{num(detail.metrics.current.alpha_t,3)}}</span><span>近似95%區間 {{alphaInterval(detail)}}／日（未校正多重比較）</span><p>平均個股含息日報酬 − 目前β × 平均基準含息日報酬。使用這次120日回歸自己的誤差資料；無風險日利率近似為0，不是未來獲利預測。</p></div><div class="ab-detail-grid"><article><small>目前曝險β（事後120日）</small><strong>{{num(detail.metrics.current.beta)}}</strong><span>HAC近似95%區間 {{num(detail.metrics.current.ci[0])}}～{{num(detail.metrics.current.ci[1])}}</span></article><article><small>計分β（60日評估期之前固定）</small><strong>{{num(detail.metrics.fixed.fit.beta)}}</strong><span>事前殘差日波動 {{num(detail.metrics.fixed.fit.sigma*100)}}%</span><span>{{detail.metrics.fixed.estimate_start}}～{{detail.metrics.fixed.estimate_end}}</span></article><article><small>60日歷史評估區間</small><strong class="ab-date">{{detail.metrics.fixed.start}}～{{detail.metrics.fixed.end}}</strong><span>個股含息複利報酬 {{pct(detail.metrics.return60)}}</span><span>最大回撤 {{pct(detail.metrics.max_drawdown)}}</span></article><article><small>β解釋度與週資料對照</small><strong>R² {{num(detail.metrics.current.r2)}}</strong><span>日β標準誤 {{num(detail.metrics.current.se,3)}}（HAC 5日）</span><span>27個完整週β {{num(detail.metrics.weekly_beta)}} · 估計期間不同，僅供對照</span></article></div><div v-if="chart" class="ab-chart"><h3>60日β調整超額走勢（日報酬加總）</h3><div class="ab-chart-bounds"><span>縱軸上界 {{pct(chart.hi,2)}}</span><span>縱軸下界 {{pct(chart.lo,2)}}</span></div><svg viewBox="0 0 600 170" role="img" :aria-label="detail.name+'六十日β調整超額加總走勢'"><line x1="35" x2="565" :y1="chart.zero" :y2="chart.zero" stroke="#c8d1c6" stroke-dasharray="4 4"/><text x="2" y="20">{{num(chart.hi,1)}}%</text><text x="2" y="144">{{num(chart.lo,1)}}%</text><polyline :points="chart.fixed" fill="none" stroke="#3d715d" stroke-width="2.6"/><polyline :points="chart.rolling" fill="none" stroke="#5489b2" stroke-width="2.2"/><text x="35" y="165">{{detail.metrics.fixed.start}}</text><text x="565" y="165" text-anchor="end">{{detail.metrics.fixed.end}}</text></svg><div class="ab-endpoints"><span><i class="fixed-key"></i>固定版期末 <strong>{{pct(detail.metrics.fixed.car)}}</strong></span><span><i class="rolling-key"></i>滾動版期末 <strong>{{pct(detail.metrics.rolling.car)}}</strong></span></div><p>上下界是兩條線共用的座標範圍，含0起點；不是期末值。</p></div><p>β較60交易日前變化 {{num(detail.metrics.beta_change.value)}}；差值區間 {{num(detail.metrics.beta_change.ci[0])}}～{{num(detail.metrics.beta_change.ci[1])}}，已考慮重疊樣本。</p></div><div class="ab-disposition-detail"><h3>當次處置判斷：{{dispositionLabel(detail)}}</h3><p>判斷日 {{detail.disposition?.screening_date}} · 來源觀測 {{detail.disposition?.observed_at}} · 預設{{detail.disposition?.excluded_by_default?'排除':'不排除'}}</p><p v-if="detail.disposition?.exclusion_reason">原因：{{detail.disposition.exclusion_reason}}</p><ul><li v-for="(e,i) in detail.disposition?.announcements||[]" :key="i">公告 {{e.published}} · 處置 {{e.start}}～{{e.end}}</li></ul></div><p>20日平均實際成交值 {{money(detail.avg_amount)}}元 · 收盤 {{num(detail.close)}}元</p><p v-if="detail.metadata_index">原追蹤指數：{{detail.metadata_index}}</p><p v-if="detail.foreign_source_day">海外已收盤基準日：{{detail.foreign_source_day}}</p><ul><li v-for="f in detail.flags" :key="f">{{f}}</li></ul><p class="ab-note">分數、α大小與區間不能直接解讀為買入建議或勝率。</p></section></div>
</div>
